"""Writes a diagram set: one SVG per diagram, a Markdown page that shows them, a one-page HTML, a JSON
summary.

The Markdown page uses plain image links, which the built-in VS Code Markdown preview shows with no extension,
and keeps the Mermaid text in a collapsed block for viewers that render it.
"""

from __future__ import annotations

import json
import os
import tempfile
from dataclasses import dataclass, field
from html import escape
from pathlib import Path

from baton.doclint import to_ascii

GENERATED = (
    "<!-- generated by `baton diagram`: change the spec or the code and re-run, never edit this file -->"
)


@dataclass
class Section:
    heading: str
    file: str  # svg file name in the set
    svg: str
    mermaid: str = ""
    lead: str = ""  # one line under the heading
    level: int = 2


@dataclass
class DiagramSet:
    title: str
    intro: str
    sections: list[Section] = field(default_factory=list)
    tables: list[tuple[str, str]] = field(default_factory=list)  # (heading, markdown table) shown first
    notes: list[str] = field(default_factory=list)
    summary: dict = field(default_factory=dict)


def _write(path: Path, text: str) -> None:
    """ASCII only: names from the code or the story can carry anything; markup files keep XML safe."""
    text = to_ascii(text, xml=path.suffix in (".svg", ".html"))
    path.parent.mkdir(parents=True, exist_ok=True)
    handle, temp = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.")
    with os.fdopen(handle, "w", encoding="utf-8") as out:
        out.write(text)
    os.replace(temp, path)


def write(out: Path, diagrams: DiagramSet) -> list[str]:
    """Writes the set into `out`; removes SVGs a previous run wrote that this run did not. Returns file
    names."""
    out.mkdir(parents=True, exist_ok=True)
    written = []
    for section in diagrams.sections:
        _write(out / section.file, section.svg)
        written.append(section.file)
    for stale in sorted(out.glob("*.svg")):
        if (
            stale.name not in written
            and stale.read_text(encoding="utf-8", errors="replace").find("baton-diagram") >= 0
        ):
            stale.unlink()
    _write(out / "diagrams.md", markdown(diagrams))
    _write(out / "index.html", html(diagrams))
    summary = {**diagrams.summary, "files": written + ["diagrams.md", "index.html"]}
    _write(out / "diagrams.json", json.dumps(summary, indent=2, sort_keys=True) + "\n")
    return summary["files"] + ["diagrams.json"]


def markdown(diagrams: DiagramSet) -> str:
    lines = [GENERATED, f"# {diagrams.title}", "", diagrams.intro, ""]
    for heading, table in diagrams.tables:
        lines += [f"## {heading}", "", table, ""]
    for section in diagrams.sections:
        lines += [f"{'#' * section.level} {section.heading}", ""]
        if section.lead:
            lines += [section.lead, ""]
        lines += [
            f"![{section.heading}]({section.file})",
            "",
            f"Full size: [{section.file}]({section.file}), or open `index.html` in a browser"
            " to scroll and zoom.",
            "",
        ]
        if section.mermaid:
            lines += [
                "<details><summary>Mermaid source (renders on GitHub and Azure DevOps)</summary>",
                "",
                "```mermaid",
                section.mermaid.rstrip(),
                "```",
                "",
                "</details>",
                "",
            ]
    if diagrams.notes:
        lines += ["## Notes", ""] + [f"- {note}" for note in diagrams.notes] + [""]
    return "\n".join(lines)


