def _md_table_to_html(table: str) -> str:
    rows = [r.strip().strip("|").split("|") for r in table.strip().splitlines() if r.strip().startswith("|")]
    if len(rows) < 2:
        return f"<p>{escape(table)}</p>"
    head, body = rows[0], rows[2:]

    def cell(text: str) -> str:
        text = text.strip()
        for status in ("new", "changed", "removed", "impacted"):
            if text == f"**{status}**":
                return f'<span class="tag {status}">{status.upper()}</span>'
        text = escape(text)
        parts = text.split("`")
        return "".join(f"<code>{p}</code>" if i % 2 else p for i, p in enumerate(parts))

    out = ["<table><thead><tr>" + "".join(f"<th>{cell(h)}</th>" for h in head) + "</tr></thead><tbody>"]
    for row in body:
        out.append("<tr>" + "".join(f"<td>{cell(c)}</td>" for c in row) + "</tr>")
    out.append("</tbody></table>")
    return "".join(out)


def _intro_html(intro: str) -> str:
    table = "\n".join(line for line in intro.splitlines() if line.startswith("|"))
    notes = [line.split("]", 1)[-1].strip() for line in intro.splitlines() if line.startswith(">")]
    text = [line for line in intro.splitlines() if line and not line.startswith(("|", ">"))]
    out = _md_table_to_html(table) if table else ""
    out += "".join(f'<p class="intro">{escape(line)}</p>' for line in text + notes)
    return out


_SCRIPT = (
    "<script>document.querySelectorAll('[data-fit]').forEach(function(b){b.addEventListener('click',"
    "function(){var c=b.parentNode.nextElementSibling;var f=c.classList.toggle('fit');"
    "b.textContent=f?'Actual size':'Fit to width';});});</script>"
)


def html(diagrams: DiagramSet) -> str:
    nav = []
    body = []
    for i, (heading, table) in enumerate(diagrams.tables):
        anchor = f"t{i}"
        nav.append(f'<a href="#{anchor}">{escape(heading)}</a>')
        body.append(f'<section id="{anchor}"><h2>{escape(heading)}</h2>{_md_table_to_html(table)}</section>')
    for i, section in enumerate(diagrams.sections):
        anchor = f"d{i}"
        nav.append(f'<a href="#{anchor}">{escape(section.heading)}</a>')
        tag = "h2" if section.level <= 2 else "h3"
        svg = section.svg.split("?>", 1)[-1]
        lead = f'<p class="lead">{escape(section.lead)}</p>' if section.lead else ""
        mermaid = (
            f"<details><summary>Mermaid source</summary><pre>{escape(section.mermaid)}</pre></details>"
            if section.mermaid
            else ""
        )
        tools = (
            '<div class="tools"><button type="button" data-fit>Fit to width</button>'
            f'<a href="{escape(section.file)}" target="_blank" rel="noopener">Open full size</a></div>'
        )
        body.append(
            f'<section id="{anchor}"><{tag}>{escape(section.heading)}</{tag}>{lead}{tools}'
            f'<div class="card">{svg}</div>{mermaid}</section>'
        )
    if diagrams.notes:
        body.append(
            '<section><h2>Notes</h2><ul class="notes">'
            + "".join(f"<li>{escape(n)}</li>" for n in diagrams.notes)
            + "</ul></section>"
        )
    return (
        '<!doctype html>\n<html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        f"<title>{escape(diagrams.title)}</title><style>{_CSS}</style></head><body>"
        f"<header><h1>{escape(diagrams.title)}</h1>{_intro_html(diagrams.intro)}</header>"
        f"<nav>{''.join(nav)}</nav><main>{''.join(body)}</main>{_SCRIPT}</body></html>\n"
    )
